import React, { useEffect, useState } from "react";
import PrescriptionOrdersTable from "./PrescriptionOrdersTable";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../api/departmentsApi";
import { Loading } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import logisticsApi from "../../../api/logistics/logisticsApi";
import InventoryFormModal from "./InventoryFormModal";
import InventoryTable from "./InventoryTable";
import { toast, ToastContainer } from "react-toastify";

const columns = [
  { name: "Product", uid: "product_title" },
  { name: "Preparation", uid: "preparation_title" },
  { name: "Units Per Pack", uid: "units_per_pack" },
  { name: "Unit Quantity", uid: "current_unit_quantity" },
  { name: "Pack Quantity", uid: "current_pack_quantity" },
  { name: "Pack Price", uid: "pack_selling_price" },
  { name: "Unit Price", uid: "unit_selling_price" },
  { name: "Destination", uid: "entity_sub_store_name" },
  { name: "Manufactured", uid: "manufacture_date" },
  { name: "Expires", uid: "expiry_date" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function InventoryList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const [user, setUser] = useState();
  const navigate = useNavigate();
  const [selectedInventoryItem, setselectedInventoryItem] = useState();
  const [entitySubStoreReceipts, setentitySubStoreReceipts] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);
  const [errors, setErrors] = useState([])

  const getEntitySubStoreReceiptsApi = useApi(logisticsApi.logisticsAdminAction);

  const { loggedInUser } = useStateContext();

  const getEntitySubStoreReceipts = async (data) => {
   
    await getEntitySubStoreReceiptsApi.request({
      action: "GetEntitySubStoreReceipts",
     
    });
  };

  useEffect(() => {
    if (getEntitySubStoreReceiptsApi.data) {
      if (getEntitySubStoreReceiptsApi.data.length) {
        setentitySubStoreReceipts(getEntitySubStoreReceiptsApi.data);
      }
    }
  }, [getEntitySubStoreReceiptsApi.data]);

  useEffect(() => {
    if (loggedInUser !== null && loggedInUser.entity_id !== null) {
      getEntitySubStoreReceipts(loggedInUser.entity_id);
    }

  }, []);

  useEffect(() => {
    setdata(entitySubStoreReceipts);
  }, [entitySubStoreReceipts]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedInventoryItem(item);
    setmodalTitle(`Edit ${item.title}`);
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new inventory item");
    setselectedInventoryItem(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (getEntitySubStoreReceiptsApi.data && getEntitySubStoreReceiptsApi.data.length) {
      setentitySubStoreReceipts(getEntitySubStoreReceiptsApi.data);
    }
    console.log("getDepartmentsActionsApi.data", getEntitySubStoreReceiptsApi.data);
  }, [getEntitySubStoreReceiptsApi.data]);

  useEffect(() => {
    if (updated === true) {
      if (loggedInUser !== null && loggedInUser.entity_id !== null) {
        getEntitySubStoreReceipts(loggedInUser.entity_id);
      }
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(entitySubStoreReceipts);
  }, [entitySubStoreReceipts]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      entitySubStoreReceipts &&
      entitySubStoreReceipts.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        entitySubStoreReceipts.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(entitySubStoreReceipts);
    }
  };

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);



  return getEntitySubStoreReceiptsApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
        <ToastContainer theme="colored" position="bottom-center" />
        {openInventoryFormModal && (
          <InventoryFormModal
            ismodalOpen={openInventoryFormModal}
            setisModalOpen={setopenInventoryFormModal}
            selectedInventoryItem={selectedInventoryItem}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
            errors={errors}
            setErrors={setErrors}
          />
        )}

        <InventoryTable
      title={"Stock Inventory"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default InventoryList;
