import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  Loading,
} from "../../../components";

import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import makeAnimated from "react-select/animated";
import retailerReceiptsApi from "../../../api/retailers/retailerReceiptsApi";
import productsApi from "../../../api/productsApi";
import entitiesApi from "../../../api/entitiesApi";
import discountsApi from "../../../api/discountsApi";
import dayjs from "dayjs";
import "dayjs/locale/en-gb";
import { Modal } from "antd";
import logisticsApi from "../../../api/logistics/logisticsApi";

export default function InventoryFormModal({
  ismodalOpen,
  setisModalOpen,
  selectedInventoryItem,
  modalTitle = "Add new retail inventory",
  updated,
  setUpdated,
  errors,
  setErrors
}) {
  const moment = require("moment");


  const entitySubStorereceiptsApi = useApi(
    logisticsApi.logisticsAdminAction
  );

  const handleEntitySubStoreReceiptstAction = async (data) => {
    await entitySubStorereceiptsApi.request(data);


  };

  useEffect(() => { }, [selectedInventoryItem]);

  useEffect(() => {
    if (entitySubStorereceiptsApi.data) {
      if (entitySubStorereceiptsApi.data.entity_sub_store_receipt) {
        toast.success(entitySubStorereceiptsApi.data.response_message)
        setisModalOpen(false)
        setUpdated(true)
      }

      if (entitySubStorereceiptsApi.data.errors) {
        setErrors(entitySubStorereceiptsApi.data.errors)
        
      }
    }
    console.log("entitySubStorereceiptsApi.data",entitySubStorereceiptsApi.data)
  }, [entitySubStorereceiptsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      manufacture_date: selectedInventoryItem
        ? selectedInventoryItem.manufacture_date
        : moment(new Date()).format("YYYY-MM-DD"),
      expiry_date: selectedInventoryItem
        ? selectedInventoryItem.expiry_date
        : moment(new Date()).format("YYYY-MM-DD"),
      batch: selectedInventoryItem ? selectedInventoryItem.batch : "",
      pack_quantity: selectedInventoryItem ? selectedInventoryItem.pack_quantity : "",
      pack_buying_price: selectedInventoryItem
        ? selectedInventoryItem.pack_buying_price
        : "",
      pack_selling_price: selectedInventoryItem
        ? selectedInventoryItem.pack_selling_price
        : "",
      source_entity: selectedInventoryItem
        ? {
          label: selectedInventoryItem.source_entity_title,
          value: selectedInventoryItem.source_entity,
        }
        : null,
      product: selectedInventoryItem
        ? {
          label: selectedInventoryItem.product_title,
          value: selectedInventoryItem.product,
        }
        : null,
      source_entity_store: selectedInventoryItem
        ? {
          label: selectedInventoryItem.source_entity_store_title,
          value: selectedInventoryItem.source_entity_store,
        }
        : null,
      entity_sub_store: selectedInventoryItem
        ? {
          label: selectedInventoryItem.entity_sub_store_title,
          value: selectedInventoryItem.entity_sub_store,
        }
        : null,
    },

    validationSchema: Yup.object({
      pack_quantity: Yup.number().min(1).required("pack quantity is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (selectedInventoryItem) {
        handleEntitySubStoreReceiptstAction({
          "action": "UpdateEntitySubStoreReceipt",
          "entity_sub_store_receipt":selectedInventoryItem.id,
          "pack_quantity":values.pack_quantity,
          "pack_buying_price":values.pack_buying_price,
          "pack_selling_price":values.pack_selling_price,
          "manufacture_date":values.manufacture_date,
          "expiry_date":values.expiry_date,
          "batch":values.batch
         
         
      });
      } else {
        handleEntitySubStoreReceiptstAction({
          "action": "CreateEntitySubStoreReceipt",
          "entity_sub_store":values.entity_sub_store.value,
          "product":values.product.value,
          "pack_quantity":values.pack_quantity,
          "pack_buying_price":values.pack_buying_price,
          "pack_selling_price":values.pack_selling_price,
          "manufacture_date":values.manufacture_date,
          "expiry_date":values.expiry_date,
          "batch":values.batch
         
         
      });
      }

      // resetForm();
    },
  });

  //Load products

  const searchProductsApi = useApi(productsApi.productsAction);

  const searchProducts = async (data) => {
    await searchProductsApi.request(data);
  };
  const [products, setProducts] = useState();
  const loadProductsOptions = async (inputText = "", callback) => {
    searchProducts({
      action: "SearchProducts",
      searchQuery: inputText,
    });
    callback(products.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchProductsApi.data) {
      if (searchProductsApi.data.length) {
        setProducts(searchProductsApi.data);
      }
    }
    console.log("searchProductsApi.data", searchProductsApi.data);
  }, [searchProductsApi.data]);

  //Load wholesalers

  const searchEntitiesApi = useApi(entitiesApi.entitiesAction);

  const searchEntities = async (data) => {
    await searchEntitiesApi.request(data);
  };
  const [sources, setSources] = useState();
  const loadSourcesOptions = async (inputText = "", callback) => {
    searchEntities({
      action: "SearchEntities",
      searchQuery: inputText,
    });
    callback(sources.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchEntitiesApi.data) {
      if (searchEntitiesApi.data.length) {
        setSources(searchEntitiesApi.data);
      }
    }
    console.log("searchManufacturerApi.data", searchEntitiesApi.data);
  }, [searchEntitiesApi.data]);

  //Retrieve entity stores 
  const [entityStores, setEntityStores] = useState([]);
  const getEntityStoresApi = useApi(logisticsApi.logisticsAdminAction);
  const getEntityStores = async () => {
    await getEntityStoresApi.request({
      action: "GetEntityStores",
    });
  };

  useEffect(() => {
    getEntityStores();
  }, []);

  useEffect(() => {
    if (getEntityStoresApi.data && getEntityStoresApi.data.length) {
      setEntityStores(
        getEntityStoresApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log("priceDiscountsActionsApi.data", getEntityStoresApi.data);
  }, [getEntityStoresApi.data]);

  //Retrieve entity sub stores
  const [entitySubStores, setentitySubStores] = useState([]);
  const getEntitySubStoresApi = useApi(
    logisticsApi.logisticsAdminAction
  );
  const getEntitySubStores = async () => {
    await getEntitySubStoresApi.request({
      action: "GetEntitySubStores",
    });
  };

  useEffect(() => {
    getEntitySubStores();
  }, []);

  useEffect(() => {
    if (
      getEntitySubStoresApi.data &&
      getEntitySubStoresApi.data.length
    ) {
      setentitySubStores(
        getEntitySubStoresApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log(
      "quantityDiscountsActionsApi.data",
      getEntitySubStoresApi.data
    );
  }, [getEntitySubStoresApi.data]);

  const handleManfactureDateChange = (date, dateString) => {
    formik.setFieldValue("manufacture", dateString);
  };
  const handleExpiryDateChange = (date, dateString) => {
    formik.setFieldValue("expiry_date", dateString);
  };

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={800}
        className="w-full text-center"
        title={selectedInventoryItem ? `EDIT ${selectedInventoryItem.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-2 mt-5 gap-1 ">
            <CustomFormItem
              touched={formik.touched.entity_sub_store}
              error={formik.errors.entity_sub_store}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="entity_sub_store"
                id="entity_sub_store"
                label="Select sub store"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("entity_sub_store", value)
                }
                value={formik.values.entity_sub_store}
                placeholder="Select sub  store"
                options={entitySubStores}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.source_entity_store}
              error={formik.errors.source_entity_store}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="source_entity_store"
                id="source_entity_store"
                label="Select source store"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("source_entity_store", value)
                }
                value={formik.values.source_entity_store}
                placeholder="Select source store"
                options={entityStores}
              />
            </CustomFormItem>


            <CustomFormItem
              touched={formik.touched.source_entity}
              error={formik.errors.source_entity}
            >
              <CustomSelectAsyncSelect
                className="text-start"
                name="source_entity"
                id="source_entity"
                label="Select source entity (optional)"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("source_entity", value)
                }
                value={formik.values.source_entity}
                placeholder="Select  source entity (optional)"
                loadOptions={loadSourcesOptions}
              />
            </CustomFormItem>


            <CustomFormItem
              touched={formik.touched.product}
              error={formik.errors.product}
            >
              <CustomSelectAsyncSelect
              
                className="text-start"
                name="product"
                id="product"
                label="Select product item"
                size="large"
                onChange={(value) => formik.setFieldValue("product", value)}
                value={formik.values.product}
                placeholder="Type product name and select"
                loadOptions={loadProductsOptions}
              />
            </CustomFormItem>


            <CustomFormItem
              touched={formik.touched.pack_quantity}
              error={formik.errors.pack_quantity}
            >
              <CustomInput
                required={true}
                label="Enter pack quantity"
                id="pack_quantity"
                name="pack_quantity"
                onChange={formik.handleChange}
                placeholder="Enter pack quantity"
                size="large"
                type="number"
                value={formik.values.pack_quantity}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.pack_buying_price}
              error={formik.errors.pack_buying_price}
            >
              <CustomInput
                required={true}
                label="Enter pack buying price"
                id="pack_buying_price"
                name="pack_buying_price"
                onChange={formik.handleChange}
                placeholder="Enter pack buying price"
                size="large"
                type="number"
                value={formik.values.pack_buying_price}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.pack_selling_price}
              error={formik.errors.pack_selling_price}
            >
              <CustomInput
                required={true}
                label="Enter pack_selling_price"
                id="pack_selling_price"
                name="pack_selling_price"
                onChange={formik.handleChange}
                placeholder="Enter pack selling price"
                size="large"
                type="number"
                value={formik.values.pack_selling_price}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.batch}
              error={formik.errors.batch}
            >
              <CustomInput
                label="Enter batch number"
                id="batch"
                name="batch"
                onChange={formik.handleChange}
                placeholder="Enter batch number"
                size="large"
                type="number"
                value={formik.values.batch}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.manufacture_date}
              error={formik.errors.manufacture_date}
            >
              <CustomDatePicker
                id="manufacture_date"
                name="manufacture_date"
                size="large"
                defaultValue={dayjs(
                  formik.values.manufacture_date,
                  "YYYY-MM-DD"
                )}
                placeholder="Select manufacture date"
                onChange={handleManfactureDateChange}
                value={formik.values.manufacture_date}
                label="Select manufacture date"
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.expiry_date}
              error={formik.errors.expiry_date}
            >
              <CustomDatePicker
                defaultValue={dayjs(formik.values.expiry_date, "YYYY-MM-DD")}
                id="expiry_date"
                name="expiry_date"
                size="large"
                placeholder="Select expiry date"
                onChange={handleExpiryDateChange}
                value={formik.values.expiry_date}
                label="Select expiry date"
              />
            </CustomFormItem>
          </div>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
